import { API_URL } from "../../playwright.config";
import { PASSWORD, expect, expectStatus, test } from "../../fixtures";

// Note: the fixtures file asks that e2e tests not assert 404s or error codes for
// another tenant's data. This scenario explicitly requires the 404 and the
// "vendor_not_found" code, so the assertions below follow the scenario.

test.describe("vendor tenant isolation", () => {
  test("vendors from another tenant are invisible", { tag: "@VEN-07" }, async ({ request, apiAs }) => {
    // Arrange: create a vendor in the Globex Procurement tenant
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const globexLogin = await request.post(`${API_URL}/api/auth/login`, {
      data: { email: "member@globex.test", password: PASSWORD },
    });
    const { access_token: globexToken } = await expectStatus<{ access_token: string }>(globexLogin, 200);

    const created = await request.post(`${API_URL}/api/vendors`, {
      headers: { Authorization: `Bearer ${globexToken}` },
      data: {
        name: `Globex Vendor ${suffix}`,
        category: "software",
        contact_email: `vendor-${suffix}@globex.test`,
      },
    });
    const globexVendor = await expectStatus<{ id: string }>(created, 201);

    // Act: request that vendor by id as a Northwind member
    const member = await apiAs("member");
    const response = await member.get(`/api/vendors/${globexVendor.id}`);

    // Assert
    const body = await expectStatus(response, 404);
    expect(body.error.code).toBe("vendor_not_found");
  });
});
